-- P1-A read-only inventory for product_archive. Run with a SELECT-only account.
-- Send tabular output only; exclude credentials and row-level business data.
SET SESSION TRANSACTION READ ONLY;
START TRANSACTION READ ONLY WITH CONSISTENT SNAPSHOT;
SELECT DATABASE() AS schema_name, CURRENT_USER() AS account_name, @@read_only AS server_read_only;
SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN ('product_models','product_machine_tiers','product_variants','product_assets','packaging_models','packaging_variants','packaging_molds','product_model_packaging_links','product_machine_tier_packaging_links','product_asset_machine_tier_links','packaging_assets','mold_variant_links','file_assets') ORDER BY TABLE_NAME;
SELECT TABLE_NAME,COLUMN_NAME,DATA_TYPE,IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND (TABLE_NAME IN ('product_models','product_machine_tiers','product_variants','product_assets','packaging_models','packaging_variants','packaging_molds','product_model_packaging_links','product_machine_tier_packaging_links','product_asset_machine_tier_links','packaging_assets','mold_variant_links','file_assets') OR COLUMN_NAME IN ('product_model_id','product_machine_tier_id','product_variant_id','model_id','machine_tier_id','variant_id','packaging_variant_id','asset_id')) ORDER BY TABLE_NAME,ORDINAL_POSITION;
SELECT TABLE_NAME,INDEX_NAME,NON_UNIQUE,GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS columns_in_index FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('product_models','product_machine_tiers','product_variants','product_assets','packaging_models','packaging_variants','packaging_molds','product_model_packaging_links','product_machine_tier_packaging_links','product_asset_machine_tier_links','packaging_assets','mold_variant_links','file_assets') GROUP BY TABLE_NAME,INDEX_NAME,NON_UNIQUE ORDER BY TABLE_NAME,INDEX_NAME;
SELECT TABLE_NAME,COLUMN_NAME,CONSTRAINT_NAME,REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME IS NOT NULL AND (TABLE_NAME IN ('product_models','product_machine_tiers','product_variants','product_assets','packaging_models','packaging_variants','packaging_molds','product_model_packaging_links','product_machine_tier_packaging_links','product_asset_machine_tier_links','packaging_assets','mold_variant_links','file_assets') OR REFERENCED_TABLE_NAME IN ('product_models','product_machine_tiers','product_variants','product_assets','packaging_models','packaging_variants','packaging_molds')) ORDER BY TABLE_NAME,COLUMN_NAME;
-- Run the following exact-count block only if all listed tables and deleted_at columns exist.
SELECT 'product_models' table_name,COUNT(*) total,SUM(deleted_at IS NULL) active,SUM(deleted_at IS NOT NULL) soft_deleted FROM product_models
UNION ALL SELECT 'product_machine_tiers',COUNT(*),SUM(deleted_at IS NULL),SUM(deleted_at IS NOT NULL) FROM product_machine_tiers
UNION ALL SELECT 'product_variants',COUNT(*),SUM(deleted_at IS NULL),SUM(deleted_at IS NOT NULL) FROM product_variants
UNION ALL SELECT 'product_assets',COUNT(*),SUM(deleted_at IS NULL),SUM(deleted_at IS NOT NULL) FROM product_assets
UNION ALL SELECT 'packaging_models',COUNT(*),SUM(deleted_at IS NULL),SUM(deleted_at IS NOT NULL) FROM packaging_models
UNION ALL SELECT 'packaging_variants',COUNT(*),SUM(deleted_at IS NULL),SUM(deleted_at IS NOT NULL) FROM packaging_variants
UNION ALL SELECT 'packaging_molds',COUNT(*),SUM(deleted_at IS NULL),SUM(deleted_at IS NOT NULL) FROM packaging_molds;
SELECT 'product_model_packaging_links' table_name,COUNT(*) total,SUM(pm.id IS NOT NULL AND pm.deleted_at IS NULL AND pv.id IS NOT NULL AND pv.deleted_at IS NULL) active,SUM(pm.id IS NULL OR pv.id IS NULL) orphan,SUM((pm.deleted_at IS NOT NULL OR pv.deleted_at IS NOT NULL) AND pm.id IS NOT NULL AND pv.id IS NOT NULL) linked_to_deleted FROM product_model_packaging_links l LEFT JOIN product_models pm ON pm.id=l.product_model_id LEFT JOIN packaging_variants pv ON pv.id=l.packaging_variant_id
UNION ALL SELECT 'product_machine_tier_packaging_links',COUNT(*),SUM(mt.id IS NOT NULL AND mt.deleted_at IS NULL AND pm.id IS NOT NULL AND pm.deleted_at IS NULL AND pv.id IS NOT NULL AND pv.deleted_at IS NULL),SUM(mt.id IS NULL OR pm.id IS NULL OR pv.id IS NULL),SUM((mt.deleted_at IS NOT NULL OR pm.deleted_at IS NOT NULL OR pv.deleted_at IS NOT NULL) AND mt.id IS NOT NULL AND pm.id IS NOT NULL AND pv.id IS NOT NULL) FROM product_machine_tier_packaging_links l LEFT JOIN product_machine_tiers mt ON mt.id=l.machine_tier_id LEFT JOIN product_models pm ON pm.id=mt.model_id LEFT JOIN packaging_variants pv ON pv.id=l.packaging_variant_id;
SELECT COUNT(*) AS assets_with_variant, SUM(a.deleted_at IS NULL AND v.deleted_at IS NULL) AS active_assets_with_active_variant, SUM(a.deleted_at IS NULL AND v.deleted_at IS NOT NULL) AS active_assets_with_deleted_variant, SUM(a.deleted_at IS NULL AND v.id IS NULL) AS active_assets_with_missing_variant FROM product_assets a LEFT JOIN product_variants v ON v.id=a.variant_id WHERE a.variant_id IS NOT NULL;
SELECT COUNT(*) AS variants_with_assets FROM product_variants v WHERE EXISTS (SELECT 1 FROM product_assets a WHERE a.variant_id=v.id AND a.deleted_at IS NULL);
COMMIT;
